  const code = PLATE_CODE[homeCityId] || 34;
  const letters = "ABCDEFGHJKLMNPRSTUVYZ";
  let h = 0; for (let i = 0; i < busId.length; i++) h = (h * 31 + busId.charCodeAt(i)) >>> 0;
