    const l1 = letters[hh % letters.length], l2 = letters[Math.floor(hh / letters.length) % letters.length];
    const num = String(100 + (hh % 900));
    const candidate = `${code} ${l1}${l2} ${num}`;
    if (!existingPlates.has(candidate)) return candidate;
