  cloudy: { id: "cloudy", icon: "☁️", label: "Bulutlu", delayMin: 0, delayMax: 0, occPenalty: 0 },
  fog: { id: "fog", icon: "🌫️", label: "Sisli", delayMin: 5, delayMax: 15, occPenalty: 0.06 },
