function computeAvgFare(route, direction, stopSeqNames) {
  const table = direction === "backward" ? FARE_BWD : FARE_FWD;
  let sum = 0, count = 0;
  for (let i = 0; i < stopSeqNames.length; i++) {
    for (let j = i + 1; j < stopSeqNames.length; j++) {
      const f = table[`${stopSeqNames[i]}→${stopSeqNames[j]}`];
      if (f !== undefined) { sum += f; count++; }
    }
  }
  return count ? Math.round(sum / count) : route.base;
}
