/** Oyuncu talebi: "Baş Şoför" pozisyonu (Host Amiri ile aynı maaş/SGK) sonradan eklendi —
 * halihazırda devam eden kayıtlarda bu pozisyon hiç yoktu, seedInitialCorporateStaff'a
 * eklemek SADECE yeni oyunları etkiler. Bu yüzden her yüklemede, eğer kadroda "bas_sofor"
 * pozisyonundan HİÇ yoksa, İzmir'de 2 kişilik başlangıç kadrosu tek seferlik olarak
 * ekleniyor — sonrasında oyuncu normal işe alım/işten çıkarma akışıyla yönetiyor,
 * bu migrasyon bir daha hiç devreye girmiyor (pozisyon zaten var demektir).
 */
function migrateCorporateStaff(staff) {
  const list = Array.isArray(staff) ? staff : [];
  if (list.some((c) => c.positionKey === "bas_sofor")) return list;
  const added = Array.from({ length: 2 }, () => ({ id: uid("corp"), positionKey: "bas_sofor", cityId: "IZM", hiredDay: 0, status: "active" }));
  return [...list, ...added];
}
/** Oyuncu talebi: saha personeli (şoför/kabin memuru) maaşı artık SABİT (SAHA_WAGE_TABLE,
 * aşağıda tanımlı) — halihazırda devam eden kayıtlarda her kişi kendi işe alım anında
 * RASTGELE bir ücretle donmuştu. Her yüklemede, mevcut her şoför/kabin memurunun ücreti
 * kendi kademesinin GERÇEK sabit değerine (günlük karşılığı) sıfırlanıyor — tek seferlik
 * değil, her yükleme çalışıyor (zararsız: değer zaten doğruysa hiçbir şey değişmez), böylece
 * yeni bir kademe/rakam güncellemesi geldiğinde de mevcut kayıtlar otomatik senkron kalır.
 */
function migrateSahaWages(drivers, cabinCrew) {
  const dList = Array.isArray(drivers) ? drivers : [];
  const cList = Array.isArray(cabinCrew) ? cabinCrew : [];
  const migratedDrivers = dList.map((d) => {
    const tmpl = SAHA_WAGE_TABLE[`sofor_${d.tier}`];
    const correctWage = tmpl ? Math.round(tmpl.netSalary / 30) : d.wage;
    return d.wage === correctWage ? d : { ...d, wage: correctWage };
  });
  const correctAttendantWage = Math.round(SAHA_WAGE_TABLE.kabin_memuru.netSalary / 30);
  const migratedCrew = cList.map((c) => (c.wage === correctAttendantWage ? c : { ...c, wage: correctAttendantWage }));
  return { drivers: migratedDrivers, cabinCrew: migratedCrew };
}

