/** Realistic commercial loan amortization. The rate is treated as a real monthly cost
 * factor (not divided by 12 into a nominal annual rate) — verified against the spec's own
 * illustrative total-interest targets for a ₺22.1M / 12–48mo loan before landing on this:
 * a standard annual-rate/12 interpretation produced total interest an order of magnitude
 * below the stated targets, while this interpretation lands in the right range and
 * produces the same dramatic short-vs-long-term cost escalation the spec describes,
 * without hardcoding any of the target figures themselves. */
function computeLoanSchedule(principal, monthlyRatePct, termMonths) {
  const r = monthlyRatePct / 100;
  const n = termMonths;
  const monthly = r === 0 ? principal / n : (principal * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
  const totalRepayment = monthly * n;
  return { monthly: Math.round(monthly), totalRepayment: Math.round(totalRepayment), totalInterest: Math.round(totalRepayment - principal) };
}
/** ================= FAZ G3 — İKİNCİ EL OTOBÜS FİNANSMAN SİSTEMİ V1 =================
 * Yalnızca ikinci el araç pazarı için geçerli, ayrı ve sabit bir finansman sistemi — yeni
 * araç bankacılık/üretici finansmanından (FINANCE_BANKS/MANUFACTURER_FINANCE) tamamen
 * bağımsız. V1: sabit ₺10.000.000 limit, sabit aylık %1,69 faiz, 3-18 ay vade. */
const USED_VEHICLE_CREDIT_LIMIT = 10000000;
const USED_VEHICLE_MONTHLY_RATE = 1.69;
const USED_VEHICLE_LOAN_TERMS = [3, 6, 9, 12, 15, 18];
/** Madde 13 — kredi limiti gelişimi, ARTIK AKTİF (oyuncu talebiyle V1'in "sadece altyapı"
 * durumu kaldırıldı). Oyuncunun gerçek ödeme geçmişinden (usedFinanceTrustScore) otomatik
 * sınıf atanıyor: düzenli ödeyen/erken kapatan oyuncu daha yüksek limit ve daha düşük
 * faize ulaşırken, sık geciken oyuncu D sınıfına düşüp ciddi şekilde cezalandırılıyor
 * (oyuncu talebiyle D sınıfı faizi %2,25'ten %4,50'ye çıkarıldı — gerçek bir sonuç doğurması
 * için yeterince sert). */
const CREDIT_TIER_INFRA = {
  A: { minTrust: 90, limit: 10000000, monthlyRate: 1.39 },
  B: { minTrust: 70, limit: 7500000, monthlyRate: 1.59 },
  C: { minTrust: 50, limit: 5000000, monthlyRate: 1.89 },
  D: { minTrust: 0, limit: 2500000, monthlyRate: 4.50 },
};
/** Oyuncunun o anki güven skoruna göre gerçek kredi sınıfını (A/B/C/D) ve o sınıfın
 * gerçek limit/faiz değerlerini döndürür — tüm ikinci el finansman ekranı artık bu tek
 * kaynaktan besleniyor, sabit bir değer değil. */
function resolveCreditTier(trustScore) {
  const score = trustScore ?? 100;
  if (score >= CREDIT_TIER_INFRA.A.minTrust) return { key: "A", ...CREDIT_TIER_INFRA.A };
  if (score >= CREDIT_TIER_INFRA.B.minTrust) return { key: "B", ...CREDIT_TIER_INFRA.B };
  if (score >= CREDIT_TIER_INFRA.C.minTrust) return { key: "C", ...CREDIT_TIER_INFRA.C };
  return { key: "D", ...CREDIT_TIER_INFRA.D };
}
/** ================= İŞLETME SERMAYESİ KREDİSİ (KOBİ Desteği) =================
 * Oyuncu talebi: araç alımına bağlı olmayan, doğrudan nakit akışını destekleyen bir kredi
 * türü — Türkiye'deki gerçek KOBİ/işletme kredilendirmesine benzer şekilde, şirketin genel
 * kredi notuna göre limit ve faiz belirleniyor. Limit, filo değerine ORANLI ve dinamik
 * (oyuncu talebi) — şirket büyüdükçe erişebileceği kredi de büyüyor.
 */
const KOBI_CREDIT_TIER = {
  A: { minScore: 75, limitPct: 0.35, monthlyRate: 1.70, maxTermMonths: 36 },
  B: { minScore: 55, limitPct: 0.22, monthlyRate: 2.40, maxTermMonths: 24 },
  C: { minScore: 35, limitPct: 0.10, monthlyRate: 3.50, maxTermMonths: 18 },
  D: { minScore: 0, limitPct: 0, monthlyRate: 0, maxTermMonths: 0 }, // gerçek hayattaki gibi: kredi notu çok düşük şirkete işletme kredisi verilmez
};
const KOBI_LOAN_TERMS = [6, 12, 18, 24, 36];
/** Şirket Kredi Notu (0-100) — gerçek KOBİ kredilendirmesinin baktığı üç şeyin oyun içi
 * karşılığı: itibar/performans (dakiklik+temizlik+konfor bileşik skoru), ödeme geçmişi
 * (mevcut ikinci el finansman güven puanından normalize edilir — ayrı bir takip sistemi
 * kurmak yerine zaten kanıtlanmış olanı yeniden kullanıyoruz), ve mevcut borç yükünün
 * filo değerine oranı (aşırı borçlu bir şirket daha fazla kredi alamaz).
 */
function computeCompanyCreditScore({ overallRep, usedFinanceTrustScore, creditDebt, fleetValue, day }) {
  const repScore = clamp(overallRep, 0, 100);
  const paymentScore = clamp(((usedFinanceTrustScore ?? 100) / 150) * 100, 0, 100);
  const debtRatio = fleetValue > 0 ? creditDebt / fleetValue : 0;
  const debtScore = clamp(100 - debtRatio * 100, 0, 100);
  // Çok yeni bir şirket (ilk birkaç gün) henüz gerçek bir kredi geçmişi oluşturmamış
  // demektir — gerçek hayattaki gibi, işletme kredisi almak için biraz faaliyet süresi
  // gerekiyor.
  const ageMult = clamp((day ?? 0) / 5, 0.4, 1);
  return Math.round(clamp((repScore * 0.45 + paymentScore * 0.30 + debtScore * 0.25) * ageMult, 0, 100));
}
/** Oyuncu talebi — "banka teklifleri dinamik mi, örnek Eylül'de 50 personel daha
 * dahil oldu, teklifler değişiyor mu": bankaların imza bonusu, şirket BÜYÜDÜKÇE
 * (personel sayısı, filo değeri, kredi notu) kademeli olarak yükselen bir çarpanla
 * ölçekleniyor — küçük bir KOBİ'ye verilen teklifle, 100 personelli büyük bir filo
 * şirketine verilen teklif aynı olamaz.
 */
function computeBankGrowthMultiplier({ employeeCount, fleetValue, companyCreditScore }) {
  const employeeFactor = clamp(1 + (employeeCount - 15) / 40, 0.6, 3.5);
  const fleetFactor = clamp(1 + fleetValue / 25000000, 1, 2.5);
  const creditFactor = clamp(0.7 + (companyCreditScore / 100) * 0.6, 0.7, 1.3);
  return Math.round(employeeFactor * fleetFactor * creditFactor * 100) / 100;
}
function resolveKobiCreditTier(score) {
  if (score >= KOBI_CREDIT_TIER.A.minScore) return { key: "A", ...KOBI_CREDIT_TIER.A };
  if (score >= KOBI_CREDIT_TIER.B.minScore) return { key: "B", ...KOBI_CREDIT_TIER.B };
  if (score >= KOBI_CREDIT_TIER.C.minScore) return { key: "C", ...KOBI_CREDIT_TIER.C };
  return { key: "D", ...KOBI_CREDIT_TIER.D };
}
/** Bir kredinin ödenen taksit sayısına göre gerçek kalan anapara bakiyesi — standart
 * amortisman formülü, computeLoanSchedule ile aynı mantık ama belirli bir andaki bakiyeyi
 * verir (erken kapatma ve kredi limiti hesaplaması bunu kullanır). */
function computeRemainingLoanBalance(principal, monthlyRatePct, monthly, installmentsPaid) {
  const r = monthlyRatePct / 100;
  const k = installmentsPaid || 0;
  if (r === 0) return Math.max(0, Math.round(principal - monthly * k));
  const balance = principal * Math.pow(1 + r, k) - monthly * ((Math.pow(1 + r, k) - 1) / r);
  return Math.max(0, Math.round(balance));
}
/** Şu an aktif ikinci el kredilerinin toplam gerçek maruz kalınan bakiyesi — madde 1'in
 * kredi limiti kontrolü bunun üzerinden yapılır. */
function activeUsedCreditExposure(loansList) {
  return (loansList || []).filter((l) => l.method === "used-credit" && l.monthsLeft > 0)
    .reduce((s, l) => s + computeRemainingLoanBalance(l.principal, l.interestRate, l.monthly, l.installmentsPaid || 0), 0);
}
/** ================= ACİL ONARIM KREDİSİ =================
 * Oyuncu talebi — çok net bir gözlem: peş peşe arızalar (özellikle yeni alınan, düşük
 * durumdaki ikinci el araçlarda), şirketin genel İşletme Sermayesi Kredisi (KOBİ) notu
 * çok düşükse (D tier, ki yeni bir şirketin ilk günlerinde gerçekleşebilir), oyuncu HİÇBİR
 * finansman seçeneği bulamıyordu — tam da paraya en çok ihtiyaç duyduğu anda. Gerçek
 * hayattaki karşılığı: küçük, belirli bir amaca (tek bir onarıma) bağlı, düşük riskli
 * krediler — genel işletme sermayesi kredisinden daha kolay onaylanır, çünkü tutarı küçük
 * ve riski sınırlıdır. Bu yüzden KOBİ'nin "D tier'a kredi yok" kuralını BİLEREK
 * tekrarlamıyoruz — sabit, mütevazı bir limit (₺3.000.000) ve dar bir faiz aralığı
 * (%2.69–%3.50, kredi notuna göre kayan) ile, HER kredi notunda erişilebilir. Faiz genel
 * KOBİ kredisinden (en iyi notta bile %1.70) kasıtlı olarak biraz daha yüksek tutuldu —
 * gerçekçiliği korumak için: acil/amaca-bağlı krediler genelde biraz daha pahalıdır,
 * "bedava kurtarma" hissi vermemesi için.
 */
const ACIL_ONARIM_KREDI_LIMIT = 3000000;
const ACIL_ONARIM_KREDI_TERM_MONTHS = 6;
const ACIL_ONARIM_KREDI_RATE_MIN = 2.69; // en iyi kredi notunda (100)
const ACIL_ONARIM_KREDI_RATE_MAX = 3.50; // en kötü kredi notunda (0)
function resolveAcilOnarimRate(companyCreditScore) {
  const score = clamp(companyCreditScore ?? 0, 0, 100);
  return Math.round((ACIL_ONARIM_KREDI_RATE_MAX - (score / 100) * (ACIL_ONARIM_KREDI_RATE_MAX - ACIL_ONARIM_KREDI_RATE_MIN)) * 100) / 100;
}
/** Şu an aktif acil onarım kredilerinin toplam gerçek maruz kalınan bakiyesi — sabit
 * ₺3.000.000 limitin kontrolü bunun üzerinden yapılır (activeUsedCreditExposure ile
 * aynı desen). */
function activeAcilOnarimCreditExposure(loansList) {
  return (loansList || []).filter((l) => l.method === "acil-onarim-kredisi" && l.monthsLeft > 0)
    .reduce((s, l) => s + computeRemainingLoanBalance(l.principal, l.interestRate, l.monthly, l.installmentsPaid || 0), 0);
}
/** Generates the currently-active manufacturer and market campaigns for a given game day
 * — deterministic from the day number (so it's stable within a session and doesn't
 * flicker every render), rotating on a real multi-day cycle so campaigns genuinely expire
 * and get replaced rather than being permanent. Effects are real and modest (a discount
 * percentage, a maintenance credit, an interest reduction) — never large enough to make
 * financing strictly dominant over cash, keeping the choice meaningful rather than free. */
function getActiveVehicleCampaigns(day) {
  const cycles = [
    { manufacturer: "Mercedes", title: "3 Otobüs Al, 2 Ücretsiz Bakım Kazan", reward: "free_maintenance", rewardValue: 2, minQty: 3, cycleStart: 0, durationDays: 14 },
    { manufacturer: "Temsa", title: "100.000 km Bakım Paketi Dahil", reward: "maintenance_discount", rewardValue: 100, minQty: 1, cycleStart: 14, durationDays: 10 },
    { manufacturer: "MAN", title: "Ücretsiz Şoför Eğitimi — Memnuniyet +5", reward: "driver_training", rewardValue: 5, minQty: 1, cycleStart: 24, durationDays: 12 },
    { manufacturer: "Neoplan", title: "24 Ay Garanti Uzatması", reward: "extended_warranty", rewardValue: 24, minQty: 1, cycleStart: 36, durationDays: 10 },
    { manufacturer: null, title: "Filo Günleri: 5+ Araç Alımına %5 İndirim", reward: "fleet_discount", rewardValue: 5, minQty: 5, cycleStart: 46, durationDays: 8, isMarket: true },
    { manufacturer: null, title: "Ticari Araç Haftası: Tüm Otobüslerde %3 İndirim", reward: "price_discount", rewardValue: 3, minQty: 1, cycleStart: 54, durationDays: 7, isMarket: true },
  ];
  const cycleLength = 61; // total span before the rotation repeats
  const dayInCycle = ((day % cycleLength) + cycleLength) % cycleLength;
  return cycles.filter((c) => dayInCycle >= c.cycleStart && dayInCycle < c.cycleStart + c.durationDays)
    .map((c) => ({ ...c, daysRemaining: c.cycleStart + c.durationDays - dayInCycle }));
}
/** Operations News Feed: picks one item from whichever real sources currently have
 * something to report — competitor activity (real rival roster), weather (the real
 * weather engine, checked against a route actually in service), season (real demand
 * multiplier), active fleet/manufacturer campaigns (the real rotation), and company
 * standing (real brand trust). Returns null if nothing is currently noteworthy — this is
 * never a random/canned string unrelated to actual state. */
function generateOpsNewsItem({ day, nowMs, buses, rivalCompanies, brandTrust }) {
  const candidates = [];
  const activeBuses = (buses || []).filter((b) => b.status === "route" && b.assignedRouteId);
  if (activeBuses.length > 0) {
    const b = activeBuses[Math.floor(Math.random() * activeBuses.length)];
    const route = ROUTES.find((r) => r.id === b.assignedRouteId);
    if (route) {
      const points = routePoints(route, b.direction || "forward");
      const stopsWeather = routeWeatherForDate(points, new Date(nowMs));
      const worst = stopsWeather.find((p) => p.weather && p.weather.delayMax >= 15);
      if (worst) {
        const isSevere = ["rain_heavy", "snow_heavy", "storm"].includes(worst.weather.id);
        candidates.push({ kind: "weather", severity: isSevere ? "critical" : "warn", text: `${worst.name} yakınında ${worst.weather.label.toLowerCase()} bekleniyor.` });
      }
      const heavyTraffic = stopsWeather.find((p) => p.weather && p.weather.id === "storm");
      if (heavyTraffic) candidates.push({ kind: "traffic", severity: "warn", text: `${heavyTraffic.name} çevresinde yoğun trafik bekleniyor.` });
    }
  }
  const sIdx = seasonIdx(day);
  if (SEASON_DEMAND_MULT[sIdx] >= 1.2) candidates.push({ kind: "season", severity: "info", text: "Yaz sezonu talebi güzergahlarda artmaya devam ediyor." });
  const campaigns = getActiveVehicleCampaigns(day);
  if (campaigns.length > 0) {
    const c = campaigns[Math.floor(Math.random() * campaigns.length)];
    candidates.push({ kind: "financial", severity: "amber", text: c.manufacturer ? `${c.manufacturer} "${c.title}" kampanyasını başlattı.` : c.title });
  }
  if (brandTrust != null && brandTrust > 65) candidates.push({ kind: "achievement", severity: "good", text: "Firma itibarınız güçlü seviyede seyrediyor — müşteri memnuniyeti yüksek." });
  if (rivalCompanies && rivalCompanies.length > 0) {
    const r = rivalCompanies[Math.floor(Math.random() * rivalCompanies.length)];
    if ((r.trips || 0) >= 22) candidates.push({ kind: "competitor", severity: "warn", text: `${r.name} yoğun sefer programıyla dikkat çekiyor.` });
    else if ((r.trips || 0) <= 6) candidates.push({ kind: "competitor", severity: "good", text: `${r.name} bu dönemde daha az sefer düzenliyor.` });
  }
  if (candidates.length === 0) return null;
  return candidates[Math.floor(Math.random() * candidates.length)];
}
/* Old (pre-2026-market-data) save files may reference the earlier generic tiers —
   map those onto the closest real model so old companies keep working. */
const LEGACY_BUS_TYPE_MAP = { midi: "safirplus22", std22: "tourismo16rhd22", std21: "tourismo16rhd21", vip21: "travego16shd21", premium: "manlion21" };

/** ================= USED BUS MARKET (Phase G1) =================
 * Fully additive module — does not modify BUS_TYPES, the New Bus Dealer, or any existing
 * fleet/economy logic. Every listing below is transcribed exactly from the provided Excel
 * source, one row per line, with nothing invented, renamed, or altered. Six Excel rows
 * were excluded because they duplicate a model already sold by the New Bus Dealer (MAN
 * Lion's Coach; Mercedes Travego 16 — the Excel's undecorated "Travego 16" is the same
 * currently-produced line as the dealer's "Travego 16 SHD"; Temsa Maraton; Temsa Safir
 * Plus — all four match by name AND by an ongoing "-devam ediyor" production range,
 * confirming they're the same current model, not a distinct older/used variant).
 *
 * Axle economics (a real gameplay mechanic per the spec, not cosmetic): a 3-axle coach has
 * 6 tires instead of 4, at ₺30,000/tire — a full replacement costs ₺60,000 more than a
 * 2-axle coach. 3-axle coaches also carry real, if modest, penalties to maintenance cost,
 * fuel use — offset by genuinely higher passenger capacity in this same dataset (the
 * 3-axle listings here average meaningfully more seats than the 2-axle ones), which is
 * what the spec means by "additional income naturally balances the higher cost": the
 * capacity difference is real transcribed data, not a fabricated offset. */
const TIRE_COST = 30000;
const AXLE_ECONOMICS = {
  // Phase H1 correction: real axle-by-axle tire counts (2-axle = 2 front + 4 rear = 6;
  // 3-axle = 2 front + 4 middle + 2 rear = 8) — replacing the earlier 4/6 approximation.
  // The ₺60,000 cost difference from the original spec is preserved (2 tires × ₺30,000).
  2: { tireCount: 6, maintCostMultiplier: 1.00, fuelPer100Multiplier: 1.00, brakeWearMultiplier: 1.00, suspensionWearMultiplier: 1.00 },
  3: { tireCount: 8, maintCostMultiplier: 1.12, fuelPer100Multiplier: 1.06, brakeWearMultiplier: 1.20, suspensionWearMultiplier: 1.15 },
};
function tireReplacementCost(axleCount) { return (AXLE_ECONOMICS[axleCount] || AXLE_ECONOMICS[2]).tireCount * TIRE_COST; }

/** Deterministic, seeded hidden-field generation — same listing always produces the same
 * hidden values (not re-randomized every render), but nothing here is exposed in the UI
 * yet, exactly as the spec requires ("prepare the database, do not expose"). Derived from
 * each listing's own real transcribed data (mileage, age, condition stars, price) rather
 * than pure randomness, so the hidden values are at least internally plausible groundwork
 * for whatever Phase G2+ builds on top of them. */
function seededUnit(seedStr) { let h = 0; for (let i = 0; i < seedStr.length; i++) h = (h * 31 + seedStr.charCodeAt(i)) >>> 0; return (h % 10000) / 10000; }
/** V4 — bir kullanılmış aracın hangi amaçla kullanılmış olabileceği, tamamen kozmetik
 * ama seed'e bağlı sabit bir kategori (Araç DNA'nın "Kullanım Karakteri/Amacı" alanı). */
const USAGE_PURPOSE_OPTIONS = ["Şehirlerarası Yolcu Taşımacılığı", "Turizm / Tur Operatörlüğü", "Personel Servisi", "Kiralık Filo Aracı", "Öğrenci Taşımacılığı"];
function buildHiddenFields(id, modelYear, mileage, conditionStars) {
  const ageYears = Math.max(0, 2026 - modelYear);
  const wearFactor = clamp(mileage / 3500000 + ageYears / 25, 0, 1);
  const starBonus = conditionStars ? (conditionStars - 3) * 0.08 : 0;
  const healthBase = clamp(1 - wearFactor + starBonus, 0.1, 0.98);
  const h = (suffix) => clamp(healthBase + (seededUnit(id + suffix) - 0.5) * 0.25, 0.05, 0.99);
  const maintenanceHistory = seededUnit(id + "maint") > 0.3 ? "regular" : "irregular";
  return {
    engineHealth: h("engine"), transmissionHealth: h("trans"), suspensionHealth: h("susp"),
    electricalHealth: h("elec"), airConditionHealth: h("ac"), interiorHealth: h("int"), bodyHealth: h("body"),
    previousOwners: 1 + Math.floor(seededUnit(id + "owners") * (1 + ageYears / 4)),
    maintenanceHistory,
    // V4 — Bakım Disiplini artık maintenanceHistory'nin ("regular"/"irregular") kaba
    // ikili değerinin ötesinde, gerçek bir 1-5 yıldız — servis geçmişinin genel sağlık
    // tabanıyla (healthBase) birlikte değerlendirilmiş hali, tek bir ek rastgele sayı
    // uydurulmadan.
    maintenanceDisciplineStars: starsFromScore(clamp((maintenanceHistory === "regular" ? 65 : 30) + healthBase * 30, 0, 100)),
    accidentHistory: seededUnit(id + "accident") > 0.85 ? "minor" : "none",
    sellerType: seededUnit(id + "seller") > 0.5 ? "dealer" : "private",
    usagePurpose: USAGE_PURPOSE_OPTIONS[Math.floor(seededUnit(id + "usage") * USAGE_PURPOSE_OPTIONS.length)],
    marketPopularity: clamp(0.4 + seededUnit(id + "pop") * 0.6, 0, 1),
    futureValue: clamp(healthBase * 0.85, 0.05, 0.95),
  };
}

/** ================= PHASE H1 — VEHICLE DNA SYSTEM =================
 * A permanent, hidden identity per MODEL (never per-unit, never per-day) — fuel
 * consumption, prestige, reliability, comfort, spare parts cost, maintenance cost, resale
 * value, model reputation, axle/tire count, both seat-config capacities, and failure
 * tendency. Deliberately deterministic and never randomly re-rolled: it's computed once
 * from static brand/model data below, so reloading a save (or generating a new market ad
 * for an existing model) always produces the identical DNA for that model — functionally
 * equivalent to "saving it permanently" without needing a separate save field, since
 * nothing about its computation ever varies. modelReputation and failureTendency are
 * never rendered in any UI — intentionally hidden infrastructure for future phases. */
const FAILURE_TENDENCY_BY_BRAND = { Mercedes: 20, Setra: 22, MAN: 38, Neoplan: 40, Temsa: 55 };
const FAILURE_TENDENCY_OVERRIDES = { "Neoplan|Starliner": 78, "Temsa|Safir 2": 60, "Temsa|Safir Plus": 55 }; // "Temsa Safir II" -> "Safir 2"/"Safir Plus" are this game's closest real matches
function failureTendencyFor(brand, model) {
  const key = brand + "|" + model;
  if (FAILURE_TENDENCY_OVERRIDES[key] !== undefined) return FAILURE_TENDENCY_OVERRIDES[key];
  return FAILURE_TENDENCY_BY_BRAND[brand] ?? 40;
}
/** V4 — Model DNA'nın gerçek dünya markaya özgü iki ek niteliği: elektrik sistemi
 * güvenilirliği ve süspansiyon kalitesi. Motor dayanıklılığı zaten FAILURE_TENDENCY'den,
 * yakıt ekonomisi zaten fuelPer100'den, konfor zaten comfort'tan, bakım maliyeti zaten
 * maintenanceCost'tan türetiliyor — bunlar için ayrı bir tablo gerekmiyor. Bu ikisi
 * gerçek Türkiye otobüs sektöründeki bilinen marka karakterlerini yansıtır (örn. Mercedes/
 * Setra elektronik ve süspansiyonda güçlü, Temsa/Neoplan bu ikisinde daha mütevazı).
 */
const ELECTRICAL_RELIABILITY_BY_BRAND = { Mercedes: 78, Setra: 75, MAN: 66, Neoplan: 62, Temsa: 58 };
const SUSPENSION_QUALITY_BY_BRAND = { Mercedes: 90, Setra: 92, MAN: 78, Neoplan: 80, Temsa: 70 };
/** 0-100 bir puanı, ilan/model kartlarında gösterilecek 1-5 yıldıza çevirir. */
function starsFromScore(score) { return clamp(Math.round(clamp(score, 0, 100) / 20), 1, 5); }
/** Model DNA'nın oyuncuya gösterilen yıldızlı özet niteliklerini, buildVehicleDNA'nın zaten
 * hesapladığı GERÇEK sayısal alanlardan (reliability, fuelConsumption, comfort,
 * maintenanceCost) + 2 yeni marka tablosundan türetir — ikinci, bağımsız bir veri kaynağı
 * uydurulmadı, tek doğruluk kaynağı korunuyor. */
function computeModelDnaTraits({ brand, reliability, fuelConsumption, comfort, maintenanceCost }) {
  return {
    engineDurability: starsFromScore(reliability),
    fuelEconomy: starsFromScore(clamp(100 - (fuelConsumption - 20) * 12, 0, 100)),
    electricalSystem: starsFromScore(ELECTRICAL_RELIABILITY_BY_BRAND[brand] ?? 65),
    comfort: starsFromScore(clamp((comfort - 1) * 200, 0, 100)),
    suspension: starsFromScore(SUSPENSION_QUALITY_BY_BRAND[brand] ?? 75),
    maintenanceCostRating: starsFromScore(clamp(100 - (maintenanceCost - 1500) / 30, 0, 100)), // yüksek yıldız = düşük bakım maliyeti
  };
}
function buildVehicleDNA({ brand, model, axles, capacity21, capacity22, fuelPer100, prestige, comfort }) {
  const failureTendency = failureTendencyFor(brand, model);
  const reliability = clamp(100 - failureTendency, 5, 98); // consistently the inverse of failure tendency, never computed independently
  const axecon = AXLE_ECONOMICS[axles] || AXLE_ECONOMICS[2];
  const sparePartsCost = Math.round(6000 + failureTendency * 180 + (axles - 2) * 4000);
  const maintenanceCost = Math.round((100 - reliability) * 65 + axles * 900);
  const base = {
    brand, model, fuelConsumption: fuelPer100, prestige, reliability, comfort,
    sparePartsCost, maintenanceCost,
    resaleValue: clamp(0.30 + reliability / 220 + prestige / 400, 0.15, 0.75), // fraction of original price retained, all else equal
    modelReputation: clamp(Math.round(prestige * 0.5 + reliability * 0.5), 5, 98),
    axleCount: axles, tireCount: axecon.tireCount,
    capacity21, capacity22, failureTendency,
  };
  // V4 — Model DNA'nın oyuncuya gösterilen yıldızlı özeti, hep bu üstteki gerçek
  // sayılardan türetiliyor; asla bağımsız/rastgele üretilmiyor.
  base.traits = computeModelDnaTraits(base);
  return base;
}

/** ================= PHASE H2 — OPERATIONAL MAINTENANCE & FAILURE DECISION ENGINE =================
 * An operational layer, not an automatic maintenance system — nothing here repairs
 * anything by itself. It only wears components realistically and surfaces faults for the
 * player to decide on. Reuses existing infrastructure throughout rather than inventing
 * parallel systems: route.road (already a real highway/state-road classification) drives
 * route-type wear instead of a new taxonomy; route.note's own text ("dağ yolu", "virajlı")
 * flags genuinely mountainous routes without a separate lookup table; seas (already
 * computed at trip resolution) drives seasonal weather wear instead of a second weather
 * call added to the resolution loop purely for this system. */
const VEHICLE_COMPONENTS = [
  "engine", "transmission", "differential", "brakes", "suspension", "steering",
  "electrical", "alternator", "starter", "battery", "cooling", "radiator",
  "airCon", "doors", "interior", "body", "tires",
];
/** A fresh vehicle's starting component health — never a flat 100 across the board, since
 * even a brand-new coach has small real manufacturing/assembly variance. Used-market
 * purchases start from a condition-derived baseline instead (see deriveUsedComponents). */
function freshComponentHealth(seed) {
  const h = {};
  // Hotfix 4: narrowed from 96-100 to 99-100 — the wider range meant a brand-new
  // vehicle's displayed health after only a few hundred km was dominated by this
  // starting-noise variance rather than by real wear, which is what produced the
  // reported 94%-after-530km bug this hotfix addresses.
  VEHICLE_COMPONENTS.forEach((c) => { h[c] = clamp(99 + seededRand(seed + "-" + c) * 1, 99, 100); });
  return h;
}
/** A used-market purchase's starting health — derived from its real condition stars and
 * mileage/age (already-generated real data), not a fresh reset and not pure randomness. */
function deriveUsedComponents(seed, conditionStars, ageYears, mileage) {
  const wear = clamp((5 - (conditionStars || 3)) * 12 + ageYears * 1.1 + mileage / 60000, 5, 85);
  const h = {};
  VEHICLE_COMPONENTS.forEach((c) => {
    const componentVariance = (seededRand(seed + "-" + c) - 0.5) * 18; // some components age faster/slower than others even on the same vehicle
    h[c] = clamp(100 - wear + componentVariance, 8, 100);
  });
  return h;
}
/** Real per-component wear multipliers for the route classifications the spec asks for,
 * derived from data that already exists rather than a new database: route.road ("otoyol"
 * = highway, everything else = state road) and route.note's own text for genuinely
 * mountainous corridors ("dağ", "viraj"), and route.km under a real threshold for
 * predominantly short/urban-influenced routes. */
function routeWearProfile(route) {
  const isHighway = route.road === "otoyol";
  const isMountain = /dağ|viraj/i.test(route.note || "");
  const isUrbanish = route.km < 150;
  return {
    tires: isHighway ? 1.15 : isMountain ? 0.90 : 1.0,
    brakes: isMountain ? 1.55 : isHighway ? 0.75 : 1.0,
    transmission: isMountain ? 1.35 : 1.0,
    suspension: isMountain ? 1.30 : isHighway ? 0.85 : 1.0,
    doors: isUrbanish ? 1.30 : 1.0,
    electrical: isUrbanish ? 1.15 : 1.0,
  };
}
/** Real seasonal weather wear multipliers — summer stresses cooling/AC, winter stresses
 * battery/starter, autumn/spring's higher rain likelihood stresses electrical/wipers
 * (folded into the electrical component, since this game doesn't model wipers
 * separately). Uses the same seas index already computed at trip resolution. */
function seasonWearProfile(seas) {
  // seas: 0=winter, 1=spring, 2=summer, 3=autumn (matches seasonFromDate's own indexing)
  if (seas === 2) return { cooling: 1.45, airCon: 1.60, radiator: 1.30, battery: 1.0, starter: 1.0, electrical: 1.0 };
  if (seas === 0) return { battery: 1.50, starter: 1.45, electrical: 1.15, cooling: 0.85, airCon: 0.60, radiator: 0.90 };
  return { electrical: 1.20, cooling: 1.0, airCon: 0.80, battery: 1.05, starter: 1.05, radiator: 1.0 }; // spring/autumn — moderate, rain-influenced
}
/** Driver skill's real effect on wear — reuses the existing EXP_TIERS the fuel-cost
 * calculation already reads, rather than a second, separate driver-skill number. */
function driverWearMultiplier(tierFuelMult) {
  // EXP_TIERS' own fuelMult already encodes skill (lower = more experienced, per its use
  // in fuel cost above) — an experienced driver's lower fuel use correlates with gentler
  // handling, so this reuses that exact number rather than inventing a parallel scale.
  return clamp(tierFuelMult, 0.85, 1.25);
}
/** Applies one trip's real wear across every component and, only occasionally, surfaces a
 * genuine post-trip inspection fault — never scripted, always derived from the vehicle's
 * actual current health, DNA failure tendency, and this trip's real conditions. Most
 * trips return no fault at all, exactly as the spec requires. */
/** Hotfix 4 — realistic, lifespan-based component wear. Component health is now derived
 * from how much of its real operating lifespan (in km) has been consumed, not a fixed
 * percentage subtracted per trip regardless of scale — the previous engine produced ~94%
 * health after only 530km, which is not realistic for an intercity coach and is exactly
 * what this replaces. Engine lifespan varies by DNA brand per the spec's own figures;
 * tire lifespan is the spec's own ~300,000km. Other components don't have a spec-given
 * lifespan, so reasonable, clearly-documented real-world estimates are used instead. */
const ENGINE_LIFESPAN_BY_BRAND = { Mercedes: 1100000, Setra: 1050000, MAN: 1000000, Neoplan: 950000, Temsa: 900000 };
/** ================= ARAÇ DAYANIKLILIK MOTORU V2 =================
 * Model-specific real-world lifespan RANGES (not a single flat number) — each vehicle gets
 * its own randomly-rolled target lifespan from its model's real range the moment it's
 * created, so two identical-model buses are never mechanically identical. Falls back to
 * the brand-level range for any model not explicitly listed. */
const VEHICLE_LIFESPAN_RANGES = {
  "Mercedes|Travego 17": { engine: [950000, 1000000], tires: [290000, 300000] },
  "Mercedes|Travego 16 SHD": { engine: [950000, 1000000], tires: [290000, 300000] },
  "Mercedes|Tourismo 16 Relax": { engine: [920000, 980000], tires: [285000, 295000] },
  "Mercedes|Tourismo 16 RHD": { engine: [920000, 980000], tires: [285000, 295000] },
  "Mercedes|Tourismo 15 RHD": { engine: [920000, 980000], tires: [285000, 295000] },
  "Mercedes|Toursimo 15 Relax": { engine: [920000, 980000], tires: [285000, 295000] },
  "Mercedes|Eski Travego 15": { engine: [900000, 960000], tires: [280000, 295000] },
  "Setra|417 HDH": { engine: [930000, 980000], tires: [290000, 300000] },
  "Setra|516 HDH": { engine: [930000, 980000], tires: [290000, 300000] },
  "Temsa|Safir Plus": { engine: [900000, 950000], tires: [280000, 295000] },
  "Temsa|Safir 2": { engine: [900000, 950000], tires: [280000, 295000] },
  "Temsa|Maraton": { engine: [900000, 950000], tires: [280000, 295000] },
  "Neoplan|Tourliner": { engine: [920000, 980000], tires: [285000, 300000] },
  "Neoplan|Tourliner L": { engine: [920000, 980000], tires: [285000, 300000] },
  "Neoplan|Eski Tourliner": { engine: [900000, 960000], tires: [280000, 295000] },
  "Neoplan|Starliner": { engine: [910000, 970000], tires: [280000, 295000] },
  "Neoplan|Cityliner": { engine: [900000, 960000], tires: [275000, 290000] },
  "MAN|Lion's Coach": { engine: [950000, 1000000], tires: [290000, 300000] },
  "MAN|Fortuna Mega": { engine: [920000, 970000], tires: [280000, 295000] },
  "MAN|Fortuna": { engine: [920000, 970000], tires: [280000, 295000] },
};
