const MAINTENANCE_FIRST_SERVICE_KM = 50000; // sıfır km bir araçta ilk (küçük) bakım
const MAINTENANCE_SECOND_SERVICE_KM = 120000; // sıfır km bir araçta ikinci (genel) bakım
const MAINTENANCE_USED_FIRST_INTERVAL_KM = 70000; // ikinci el alınan bir araçta alım km'sinden itibaren ilk uyarı
const MAINTENANCE_RECURRING_INTERVAL_KM = 60000; // ondan sonraki her tekrar
