function initialMaintenanceScheduleForNewBus() {
  return { nextServiceDueKm: MAINTENANCE_FIRST_SERVICE_KM, nextServiceType: "kucuk" };
}
/** İkinci el alınan bir araç için ilk bakım hedefini kurar — "yağ değişimi yeni yapılmış"
 * varsayımıyla, alım km'sinden itibaren. */
