  const weights = [
    0.05 + oldBias * 0.35,       // 1 star
    0.10 + oldBias * 0.25,       // 2 stars
    0.30,                          // 3 stars (always a solid middle chance)
    0.30 - oldBias * 0.15,       // 4 stars
    0.25 - oldBias * 0.20,       // 5 stars
  ].map((w) => Math.max(0.02, w));
  const total = weights.reduce((s, w) => s + w, 0);
