  const excelMF = mileageFactorForAge(excelMileage, excelAge);
  const yearSensitivity = MODEL_YEAR_SENSITIVITY[brand + "|" + model] || 1.0;
  const yearRatio = 1 + ((yf / excelYF) - 1) * yearSensitivity;
