function generateDailyUsedMarket(day) {
  // Oyuncu talebi (İkinci El sekmesiyle birleştirme + ilan sayısı 25'e çıkarma): havuzda
  // artık 23 benzersiz marka+model var (44 satırın çoğu aynı modelin farklı yaş/km/fiyatlı
  // tekrarı — oyuncunun ikinci Excel tablosuyla 9 yeni model daha eklendi) — 25 ilan için
  // tek-modelli eski kısıtlama artık uygulanmıyor, aynı model GÜNDE BİRDEN FAZLA kez
  // (farklı yaş/km/durum/fiyatla, bağımsız birer ilan olarak) çıkabiliyor. Yeni modeller
  // ilerleyen oturumlarda USED_BUS_LISTINGS'e eklendikçe çeşitlilik kendiliğinden artacak,
  // bu fonksiyonda hiçbir değişiklik gerekmeyecek.
  const byModel = {};
  USED_BUS_LISTINGS.forEach((v) => {
    const key = v.brand + "|" + v.model;
    if (!byModel[key]) byModel[key] = [];
    byModel[key].push(v);
  });
  const uniqueModelKeys = Object.keys(byModel);
  const representativePool = uniqueModelKeys.map((key) => {
    const candidates = byModel[key];
    if (candidates.length === 1) return candidates[0];
    const pickSeed = seededRand(`day${day}-rep-${key}`);
    return candidates[Math.floor(pickSeed * candidates.length)];
  });
  const LISTING_COUNT = 25;
  // Sıralamayı karıştırıp gerektiği kadar tekrarla döngüye alıyoruz — havuz 25'ten küçük
  // olsa bile (şu an 14), her tam turdan sonra yeniden bağımsız karıştırılarak devam
  // ediyor, aynı modelin aynı günde birden fazla çıkması artık kasıtlı ve beklenen.
  const shuffled = [];
  let round = 0;
  while (shuffled.length < LISTING_COUNT) {
    const roundShuffled = representativePool
      .map((v, i) => ({ v, key: seededRand(`day${day}-shuffle-r${round}-${v.id}-${i}`) }))
      .sort((a, b) => a.key - b.key)
      .map((x) => x.v);
    shuffled.push(...roundShuffled);
    round += 1;
  }
  const finalPool = shuffled.slice(0, LISTING_COUNT);
  return finalPool.map((v, idx) => {
    // BUG FIX (aynı modelin aynı günde birden fazla ilan olarak çıkabilmesiyle birlikte):
    // seedBase eskiden sadece day+v.id'ye dayanıyordu — aynı model iki kez seçilince İKİ
    // ilan da BİREBİR AYNI yaş/km/durum/fiyatla üretilirdi. Artık ilanın kendi sıradaki
    // index'i de seed'e katılıyor, her tekrar bağımsız ve gerçekçi şekilde farklılaşıyor;
    // adId de bu yüzden index içeriyor, aksi halde aynı gün içindeki iki kopya ilan aynı
    // adId'yi paylaşıp birbirinin yerine geçebilir (satın alma/kaldırma karışırdı).
    const seedBase = `day${day}-ad-${v.id}-${idx}`;
    const dna = vehicleDNAFor(v.brand, v.model);
    // Phase H1: randomly choose 2+1 or 2+2 for this specific ad, assigning the
    // permanent DNA capacity for whichever config is drawn — never known in advance.
    const configSeed = seededRand(seedBase + "-config");
    const genConfig = configSeed < 0.5 ? "2+1" : "2+2";
    const genCapacity = dna ? (genConfig === "2+1" ? dna.capacity21 : dna.capacity22) : v.capacity;
    const { startYear, endYear } = parseProductionRange(v.productionRange);
    const yearSeed = seededRand(seedBase + "-year");
    const genModelYear = Math.round(startYear + yearSeed * (endYear - startYear));
    const age = Math.max(0, 2026 - genModelYear);
    const range = mileageRangeForAge(age);
    const mileageSeed = seededRand(seedBase + "-mileage");
    const genMileage = Math.round(range.min + mileageSeed * (range.max - range.min));
    const starSeed = seededRand(seedBase + "-stars");
    let conditionStars = generateConditionStars(age, starSeed);
    const isSpecial = seededRand(seedBase + "-special") < 0.05; // ~5% per the bonus requirement
    let special = null;
    let genMileageFinal = genMileage;
    if (isSpecial) {
      const pick = SPECIAL_OPPORTUNITY_TYPES[Math.floor(seededRand(seedBase + "-specialtype") * SPECIAL_OPPORTUNITY_TYPES.length)];
      special = pick;
      if (pick.mileageMult) genMileageFinal = Math.round(genMileage * pick.mileageMult);
      if (pick.conditionBoost) conditionStars = clamp(conditionStars + pick.conditionBoost, 1, 5);
    }
    const priceSeed = seededRand(seedBase + "-price");
    const hiddenFields = buildHiddenFields(`day${day}-${v.id}-${idx}`, genModelYear, genMileageFinal, conditionStars);
    let price = computeVehicleMarketPrice({
      brand: v.brand, model: v.model, genModelYear, genMileage: genMileageFinal, conditionStars, hiddenFields, seed: priceSeed,
      excelModelYear: v.modelYear, excelMileage: v.mileage, excelConditionStars: v.conditionStars || 3, excelPrice: v.price,
    });
    if (special && special.priceMult) price = Math.min(marketValueFor(v.brand, v.model), Math.round(price * special.priceMult / 10000) * 10000);
    const axecon = AXLE_ECONOMICS[v.axles] || AXLE_ECONOMICS[2];
    const closestNew = Object.values(BUS_TYPES).reduce((best, t) => (Math.abs(t.capacity - v.capacity) < Math.abs(best.capacity - v.capacity) ? t : best), Object.values(BUS_TYPES)[0]);
    // V4 — parça bazlı bağımsız servis geçmişi, buradan üretilen gerçek sağlık
    // yüzdeleri, servis sınıfı ve ilan etiketleri. Aynı seed tabanı (adId) satın alma
    // anında da tekrar kullanılacak ki ilanda görülen ile satın alınan araç birebir aynı
    // olsun.
    const serviceHistory = rollComponentServiceHistory(`day${day}-${v.id}-${idx}`, genMileageFinal);
    const componentHealth = componentHealthFromService(serviceHistory);
    const serviceClass = computeServiceClass(hiddenFields, componentHealth);
    const tags = computeListingTags(serviceHistory, componentHealth, hiddenFields);
    return {
      adId: `day${day}-${v.id}-${idx}`, poolId: v.id, brand: v.brand, model: v.model, axles: v.axles,
      config: genConfig, capacity: genCapacity, tireCount: axecon.tireCount, tireReplacementCost: tireReplacementCost(v.axles),
      modelYear: genModelYear, mileage: genMileageFinal, conditionStars, price, special,
      fuelPer100: Math.round(closestNew.fuelPer100 * axecon.fuelPer100Multiplier),
      maintCostPerKm: Math.round(closestNew.maintCostPerKm * axecon.maintCostMultiplier * 100) / 100,
      insuranceMonthly: Math.round(closestNew.insuranceMonthly * 0.75), taxMonthly: closestNew.taxMonthly,
      konfor: Math.round(30 + conditionStars * 12), prestij: Math.round(25 + conditionStars * 10),
      speedFactor: 0.95, comfort: 1.0 + conditionStars * 0.06,
      hidden: hiddenFields, serviceHistory, componentHealth, serviceClass, tags,
    };
  });
}

