async function clearAllSavedGameData() {
  delete memoryStore[SAVE_KEY];
  delete memoryStore[SAVE_KEY_BACKUP];
  if (hasLocalStorage()) {
    try { window.localStorage.removeItem("bmt_" + SAVE_KEY); } catch (e) { console.warn("[storage] localStorage.removeItem failed:", e); }
    try { window.localStorage.removeItem("bmt_" + SAVE_KEY_BACKUP); } catch (e) { console.warn("[storage] localStorage.removeItem failed:", e); }
  }
  if (typeof window !== "undefined" && window.storage && typeof window.storage.delete === "function") {
    try { await window.storage.delete("bmt_" + SAVE_KEY, false); } catch (e) { console.warn("[storage] window.storage.delete failed:", e && e.message); }
    try { await window.storage.delete("bmt_" + SAVE_KEY_BACKUP, false); } catch (e) { console.warn("[storage] window.storage.delete failed:", e && e.message); }
  }
}
/** Writes to both the primary slot and a backup slot. The backup is written with the
 * state from BEFORE this save (not a copy of the same data) whenever possible, so if a
 * write is interrupted mid-way and corrupts the primary slot, the backup still holds a
 * genuinely different, previously-known-good save rather than a duplicate of the same
 * write that might have failed. */
let lastKnownGoodSnapshot = null;
async function saveGameState(snapshotJson) {
  if (lastKnownGoodSnapshot) await safeStorageSet(SAVE_KEY_BACKUP, lastKnownGoodSnapshot);
  const res = await safeStorageSet(SAVE_KEY, snapshotJson);
  lastKnownGoodSnapshot = snapshotJson;
  return res;
}
/** Loads the primary save; if it's missing or fails to parse (corrupted), transparently
 * falls back to the backup slot instead of dropping the player back to a new game. */
async function loadGameStateWithFailsafe() {
  const primary = await safeStorageGet(SAVE_KEY);
  if (primary.result && primary.result.value) {
    try {
      const parsed = JSON.parse(primary.result.value);
      return { parsed, raw: primary.result.value, usedBackup: false, persistent: primary.persistent };
    } catch (e) {
      console.warn("[save] primary save is corrupted, falling back to backup:", e);
    }
  }
  const backup = await safeStorageGet(SAVE_KEY_BACKUP);
  if (backup.result && backup.result.value) {
    try {
      const parsed = JSON.parse(backup.result.value);
      return { parsed, raw: backup.result.value, usedBackup: true, persistent: backup.persistent };
    } catch (e) {
      console.warn("[save] backup save is also corrupted:", e);
    }
  }
  return { parsed: null, raw: null, usedBackup: false, persistent: primary.persistent };
}
// BUG FIX (oyuncu bildirdi — "personel isim-soyisimleri aynı olmasın, hangi Murat Aksoy
// olduğunu ayırt edemiyorum"): eskiden tek bir "Ad Soyad" havuzundan (16 tam isim) rastgele
// seçiliyordu — birkaç personelden sonra bile tam isim çakışması kaçınılmazdı. Artık ad ve
// soyad AYRI havuzlardan, mevcut TÜM personelle (şoför+kabin memuru birlikte, kullanıcı
// talebiyle) ÇAKIŞMAYAN bir kombinasyon garanti edilerek seçiliyor — bkz. generateUniqueName.
const FIRST_NAMES = ["Mehmet", "Ahmet", "Mustafa", "Hasan", "İbrahim", "Ali", "Hüseyin", "Osman", "Kemal", "Recep", "Emre", "Murat", "Fatma", "Ayşe", "Zeynep", "Elif", "Fatih", "Serkan", "Cem", "Burak", "Selim", "Gökhan", "Cengiz", "Tolga"];
const LAST_NAMES = ["Yılmaz", "Demir", "Kaya", "Çelik", "Şahin", "Yıldız", "Aydın", "Arslan", "Doğan", "Kurt", "Öztürk", "Aksoy", "Güneş", "Polat", "Kaplan", "Tekin", "Şimşek", "Çetin", "Korkmaz", "Özdemir", "Karaca", "Erdoğan", "Bulut"];
/** Mevcut TÜM personelin (drivers + cabinCrew, ikisi birlikte) tam isimleriyle asla
 * çakışmayan yeni bir "Ad Soyad" üretir. 24×23=552 olası kombinasyon var — gerçekçi filo
 * büyüklüklerinde tükenmesi neredeyse imkansız, ama yine de tükenirse (aşırı büyük filo)
 * en son çare olarak numaralandırılmış bir varyant üretir, sonsuz döngüye asla girmez. */
function generateUniqueName(existingPeople) {
  const taken = new Set((existingPeople || []).map((p) => p.name));
  for (let attempt = 0; attempt < 200; attempt++) {
    const first = FIRST_NAMES[Math.floor(Math.random() * FIRST_NAMES.length)];
    const last = LAST_NAMES[Math.floor(Math.random() * LAST_NAMES.length)];
    const candidate = `${first} ${last}`;
    if (!taken.has(candidate)) return candidate;
  }
  // 200 denemede bile boş kombinasyon bulunamadıysa (çok büyük bir filo demektir) — sonsuz
  // döngüye girmek yerine, güvenli bir numaralandırılmış varyantla devam eder.
  const first = FIRST_NAMES[Math.floor(Math.random() * FIRST_NAMES.length)];
  const last = LAST_NAMES[Math.floor(Math.random() * LAST_NAMES.length)];
  let n = 2;
  while (taken.has(`${first} ${last} ${n}`)) n++;
  return `${first} ${last} ${n}`;
}


