          ticketPrice: 0, direction: firstHop.direction, depAt, arrAt, skippedStops: [], seatPlan: {}, initialSeatPlan: {}, priceMatrix: {},
          catering: "standart", cateringCount: 0, repeatMode: "once",
          reallocatedStops: [], extraReceived: {}, seatsReleased: {}, optimizationLog: [], pendingReallocation: null,
