    drivers.forEach((d) => { const busId = findBusForStaff(d.id, true); if (busId) driverPins[d.id] = busId; });
    const attendantPins = {};
    cabinCrew.forEach((c) => { const busId = findBusForStaff(c.id, false); if (busId) attendantPins[c.id] = busId; });

    const idleBusesForPinning = buses.filter((b) => b.status === "idle");
    const busDriverCount = {}, busAttendantCount = {};
    idleBusesForPinning.forEach((b) => { busDriverCount[b.id] = 0; busAttendantCount[b.id] = 0; });
    Object.values(driverPins).forEach((busId) => { if (busDriverCount[busId] !== undefined) busDriverCount[busId]++; });
    Object.values(attendantPins).forEach((busId) => { if (busAttendantCount[busId] !== undefined) busAttendantCount[busId]++; });

    const unpinnedIdleDrivers = drivers.filter((d) => d.status === "idle" && !driverPins[d.id]);
