      const freedAttendantIds = isActiveSlotOnOldBus ? (swapFromBus.attendantIds || []) : (queuedConflictEntry ? (queuedConflictEntry.attendantIds || []) : []);
      if (freedDriverIds.length > 0) setDrivers((ds) => ds.map((d) => (freedDriverIds.includes(d.id) ? { ...d, status: "idle" } : d)));
      if (freedAttendantIds.length > 0) setCabinCrew((cs) => cs.map((c) => (freedAttendantIds.includes(c.id) ? { ...c, status: "idle" } : c)));
