        const isActiveTripConflict = bus.status === "route" && bus.depAt != null && bus.assignedRouteId &&
          (() => { const r = ROUTES.find((rr) => rr.id === bus.assignedRouteId); if (!r) return false; const aArr = bus.depAt + effectiveHours(r, (bus.skippedStops || []).length, bus.direction) * 3600000; const readyMs = (turnaroundMin || 0) * 60000; return depAt < aArr + readyMs && bus.depAt < arrAt; })();
