        const conflictAt = slotConflictPrompt.swapSlotDepAt ?? slotConflictPrompt.depAt;
        const depName = conflictRoute ? (conflictDir === "backward" ? CITIES[conflictRoute.to]?.name : CITIES[conflictRoute.from]?.name) : "";
