          {showDirectionToggle && route.oneWayOnly && <span className="disp text-[10px] px-2 py-1 rounded" style={{ background: "rgba(242,169,59,0.15)", color: C.amber }}>{CITIES[route.from].name} → {CITIES[route.to].name} (tek yönlü hat)</span>}
