function Row({ label, v, pos, bold }) {
  return <div className="flex justify-between" style={{ color: bold ? (v >= 0 ? C.green : C.red) : C.textMid, fontWeight: bold ? 700 : 400 }}><span>{label}</span><span>{v >= 0 ? "+" : ""}₺{fmt(v)}</span></div>;
}
/** Trip Financial Report — shown once a trip genuinely completes (not cancelled). Cash
 * was already updated atomically at resolution (the same single cashDelta application
 * that's always applied there — this report doesn't gate or delay that), so this is
 * presenting a completed transaction, not requesting authorization for one. Deliberately
 * excludes personnel and catering costs from the displayed breakdown, per the current
 * accounting scope — those remain future-phase systems, not omitted by accident. */
function TripFinancialReportModal({ entry, onClose }) {
  const originName = entry.direction === "backward" ? CITIES[entry.route.to].name : CITIES[entry.route.from].name;
  const destName = entry.direction === "backward" ? CITIES[entry.route.from].name : CITIES[entry.route.to].name;
  const totalExpenses = entry.termFee + entry.fuelCost + entry.tollCost;
  const fuelPct = totalExpenses > 0 ? Math.round((entry.fuelCost / totalExpenses) * 100) : 0;
  const netProfit = Math.round(entry.revenue - totalExpenses);
  // Passenger flow statistics — derived entirely from flowBreakdown, which
  // simulateSeatFlow already computed at resolution ({stop, alighted, boarded,
  // onboardAfter} for every stop). Nothing here is a new tracking system; it's the first
  // time this already-computed data has been displayed. Ticket Sold / Passengers
  // Transported here are trip-completion statistics, distinct from the Active Trip card's
  // live Current Passengers On Board — never the same value, per the "never mix them" rule.
  const flow = Array.isArray(entry.flowBreakdown) ? entry.flowBreakdown : [];
  const maxOnboard = flow.length > 0 ? Math.max(...flow.map((s) => s.onboardAfter)) : (entry.passengers || 0);
  const avgOccupancyPct = (flow.length > 0 && entry.capacity)
    ? Math.round((flow.reduce((s, x) => s + x.onboardAfter, 0) / flow.length / entry.capacity) * 100)
    : (entry.capacity ? Math.round(((entry.passengers || 0) / entry.capacity) * 100) : 0);
  return (
    <div className="fixed inset-0 z-[999] flex items-center justify-center p-4" style={{ background: "rgba(0,0,0,0.75)" }}>
      <div className="rounded-2xl p-5 w-full max-w-sm" style={{ background: "#14171a", border: "1px solid #2a2e33" }}>
        <div className="text-[10px] uppercase tracking-wide mb-1" style={{ color: "rgba(255,255,255,0.4)" }}>Sefer Tamamlanma Raporu</div>
        <div className="text-sm font-bold mb-3" style={{ color: "#fff" }}>{originName} → {destName}</div>
        <div className="space-y-1 mb-2 pb-2" style={{ borderBottom: "1px solid #2a2e33" }}>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Satılan Bilet</span><span className="mono font-bold" style={{ color: "#ddd" }}>{entry.passengers}</span></div>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Taşınan Yolcu</span><span className="mono font-bold" style={{ color: "#ddd" }}>{entry.passengers}</span></div>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>En Yüksek Doluluk (Anlık)</span><span className="mono font-bold" style={{ color: "#ddd" }}>{maxOnboard} / {entry.capacity}</span></div>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Ortalama Doluluk</span><span className="mono font-bold" style={{ color: "#ddd" }}>%{avgOccupancyPct}</span></div>
        </div>
        <div className="space-y-1 mb-2 pb-2" style={{ borderBottom: "1px solid #2a2e33" }}>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Sefer Geliri</span><span className="mono font-bold" style={{ color: "#7ed99a" }}>₺{fmt(entry.revenue)}</span></div>
        </div>
        <div className="space-y-1 mb-2 pb-2" style={{ borderBottom: "1px solid #2a2e33" }}>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Terminal Ücretleri</span><span className="mono" style={{ color: "#ddd" }}>₺{fmt(entry.termFee)}</span></div>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Yakıt Maliyeti</span><span className="mono" style={{ color: "#ddd" }}>₺{fmt(entry.fuelCost)}</span></div>
          <div className="flex justify-between text-[11px]"><span style={{ color: "rgba(255,255,255,0.6)" }}>Geçiş/Köprü Ücreti</span><span className="mono" style={{ color: "#ddd" }}>₺{fmt(entry.tollCost)}</span></div>
        </div>
        <div className="flex justify-between text-[11px] mb-3"><span style={{ color: "rgba(255,255,255,0.6)" }}>Toplam Gider</span><span className="mono font-bold" style={{ color: "#e15c4f" }}>₺{fmt(totalExpenses)}</span></div>
        <div className="flex justify-between text-sm mb-4 pt-2" style={{ borderTop: "1px solid #2a2e33" }}>
          <span className="font-bold" style={{ color: "#fff" }}>Net Kâr</span>
          <span className="mono font-bold" style={{ color: netProfit >= 0 ? "#7ed99a" : "#e15c4f" }}>₺{fmt(netProfit)}</span>
        </div>
        <div className="rounded-lg p-3 mb-3" style={{ background: "rgba(74,144,226,0.08)" }}>
          <div className="text-[9px] disp mb-1" style={{ color: "rgba(255,255,255,0.4)" }}>OPERASYON DİREKTÖRÜ</div>
          <div className="text-[11px]" style={{ color: "#ddd", lineHeight: 1.5 }}>
            "{originName} → {destName} seferi ₺{fmt(netProfit)} net kâr üretti. Yakıt maliyeti toplam giderin %{fuelPct}'ini oluşturuyor. {netProfit < 0 ? "Bu sefer zararla sonuçlandı — bilet fiyatlarını gözden geçirmenizi veya gelecek seferlerde dolulukları artırmanızı öneririm." : fuelPct > 55 ? "Bilet fiyatlarını gözden geçirmenizi veya gelecek seferlerde dolulukları artırmanızı öneririm." : "Bu sefer sağlıklı bir kâr marjıyla tamamlandı."}"
          </div>
        </div>
        <button onClick={onClose} className="disp text-xs px-4 py-2.5 rounded w-full" style={{ background: "#2f6fed", color: "#fff" }}>TAMAM</button>
      </div>
    </div>
  );
}
